        variantId: l.variantId,
        quantity: l.quantity,
        ...(l.unitCents !== l.listCents ? { unitCents: l.unitCents } : {}),
        ...(l.discount?.kind === "percent" ? { percentOff: l.discount.percent } : {}),
        taxable: l.taxable,
