// are ux-designer's check (docs/reviews/2026-10-22-ux-designer-f2-s3.md, the words table W-1 to W-38).

import { useEffect, useMemo, useState } from "react";
import { DateRangeField } from "../../../design-system/src/forms/forms.tsx";
import type { BarAction } from "../../../design-system/src/frame/frame.tsx";
